package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MigrationConflictsAcceptance {
    static String api(String job){return TransferAcceptance.API+"/"+job+"/conflicts";}
    static String detail(String job,String id){return api(job)+"/incident/"+id;}
    static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response)throws Exception{return TransferAcceptance.result(response,200);}
    static Map<String,Object> row(int n,String title){return map("sys_id",MigrationSource.key(n),"short_description",title,"state","1","priority","3");}
    static String prepare(WorkflowSupport h,int rows)throws Exception{
        MigrationSource.reset();var source=new ArrayList<Map<String,Object>>();for(int n=1;n<=rows;n++)source.add(row(n,"Imported "+n));MigrationSource.tables.put("incident",source);String first=MigrationStopsAcceptance.create(h);TransferAcceptance.fetch(h,first);result(h.json("POST",TransferAcceptance.API+"/"+first+"/apply",map(),auth("admin")));
        try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=1;n<=rows;n++){var record=Service.record(db,"incident",MigrationSource.key(n));Service.update(db,"incident",record,map("short_description","Local "+n),"admin","admin",null);}db.connection.commit();}
        source=new ArrayList<>();for(int n=1;n<=rows;n++)source.add(row(n,"Remote "+n));MigrationSource.tables.put("incident",source);String next=result(h.json("POST",TransferAcceptance.API+"/"+first+"/sync",map(),auth("admin"))).get("job_id").toString();TransferAcceptance.fetch(h,next);return next;
    }
    static Map<String,Object> decision(Map<String,Object> view,String choice){return map("decision",choice,"reason","Reviewed version <script>","review",view.get("review"),"revision",view.get("revision"),"confirm",true);}
    static Map<String,Object> record(WorkflowSupport h,int n)throws Exception{try(var db=h.store.open()){PlatformFoundationTest.bind(db);return Service.record(db,"incident",MigrationSource.key(n));}}
    static void run(WorkflowSupport h)throws Exception{
        h.account("ConflictReader","reader");String job=prepare(h,2),one=detail(job,MigrationSource.key(1)),two=detail(job,MigrationSource.key(2));assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());var page=result(h.get(api(job)+"?limit=1",auth("admin")));assertEquals(2,page.get("total"));assertEquals(1,page.get("next_offset"));assertEquals(1,objects(result(h.get(api(job)+"?limit=1&offset=1",auth("admin"))).get("conflicts")).size());assertEquals(0,objects(result(h.get(api(job)+"?offset=10000",auth("admin"))).get("conflicts")).size());
        assertEquals(401,h.get(api(job),null).statusCode());assertEquals(403,h.get(api(job),auth("ConflictReader")).statusCode());assertEquals(403,h.get(one,auth("ConflictReader")).statusCode());assertEquals(405,h.json("POST",api(job),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(job)+"?bad=x",auth("admin")).statusCode());assertEquals(400,h.get(api(job)+"?limit=101",auth("admin")).statusCode());assertEquals(400,h.get(one+"?bad=x",auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());
        var first=result(h.get(one,auth("admin")));assertEquals("Imported 1",object(object(first.get("baseline")).get("data")).get("short_description"));assertEquals("Local 1",object(object(first.get("current")).get("data")).get("short_description"));assertEquals("Remote 1",object(first.get("mapped")).get("short_description"));
        for(var bad:List.of(map(),map("decision","bad","reason","r","review",first.get("review"),"revision",0,"confirm",true),map("decision","keep_destination","reason","","review",first.get("review"),"revision",0,"confirm",true),map("decision","keep_destination","reason","r","review",first.get("review"),"revision",0,"confirm",false))){assertEquals(400,h.json("POST",one,bad,auth("admin")).statusCode());}
        var stale=decision(first,"keep_destination");stale.put("review","stale");assertEquals(409,h.json("POST",one,stale,auth("admin")).statusCode());var saved=result(h.json("POST",one,decision(first,"keep_destination"),auth("admin")));assertEquals(1,saved.get("revision"));assertEquals(409,h.json("POST",one,decision(first,"use_source"),auth("admin")).statusCode());assertEquals("Local 1",object(record(h,1).get("data")).get("short_description"));assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());assertEquals("Local 1",object(record(h,1).get("data")).get("short_description"));
        result(h.json("POST",two,decision(result(h.get(two,auth("admin"))),"use_source"),auth("admin")));Map<String,Object> before;try(var db=h.store.open()){before=TransferApply.snapshot(db,"record",MigrationSource.key(1));}var dry=result(h.json("POST",TransferAcceptance.API+"/"+job+"/preview",map(),auth("admin")));assertEquals(true,dry.get("preview"));assertEquals("Local 2",object(record(h,2).get("data")).get("short_description"));assertEquals(2,result(h.get(api(job),auth("admin"))).get("total"));new Store(h.environment);
        result(h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")));assertEquals("Local 1",object(record(h,1).get("data")).get("short_description"));assertEquals("Remote 2",object(record(h,2).get("data")).get("short_description"));try(var db=h.store.open()){assertEquals(before,TransferApply.snapshot(db,"record",MigrationSource.key(1)));assertEquals(object(before.get("access")),RecordAccess.status(db,MigrationSource.key(2)));}
        var history=result(h.get(api(job),auth("admin")));assertEquals(false,history.get("editable"));assertEquals(2,history.get("total"));assertEquals(409,h.get(one,auth("admin")).statusCode());assertEquals("keep_destination",object(objects(history.get("conflicts")).getFirst().get("saved")).get("decision"));assertEquals(0,result(h.get(TransferAcceptance.API+"/"+job+"/reconciliation",auth("admin"))).get("changed_destinations"));
        String next=result(h.json("POST",TransferAcceptance.API+"/"+job+"/sync",map(),auth("admin"))).get("job_id").toString();TransferAcceptance.fetch(h,next);var unchanged=result(h.json("POST",TransferAcceptance.API+"/"+next+"/apply",map(),auth("admin")));assertEquals(0,object(unchanged.get("changed")).get("records"));assertEquals("Local 1",object(record(h,1).get("data")).get("short_description"));
        MigrationSource.tables.put("incident",List.of(row(1,"New remote value"),row(2,"Remote 2")));String again=result(h.json("POST",TransferAcceptance.API+"/"+next+"/sync",map(),auth("admin"))).get("job_id").toString();TransferAcceptance.fetch(h,again);result(h.json("POST",TransferAcceptance.API+"/"+again+"/apply",map(),auth("admin")));assertEquals("New remote value",object(record(h,1).get("data")).get("short_description"));
    }
    static void stale(WorkflowSupport h)throws Exception{
        String job=prepare(h,1),path=detail(job,MigrationSource.key(1));var view=result(h.get(path,auth("admin")));result(h.json("POST",path,decision(view,"use_source"),auth("admin")));
        try(var db=h.store.open()){db.update("UPDATE os_record SET revision=revision+1 WHERE sys_id=?",MigrationSource.key(1));db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
        result(h.json("POST",path,decision(result(h.get(path,auth("admin"))),"use_source"),auth("admin")));try(var db=h.store.open()){var current=TransferJobs.job(db,job);var state=object(current.get("detail"));var saved=object(object(state.get("resolutions")).get("incident:"+MigrationSource.key(1)));saved.put("auth_revision",-1);TransferJobs.save(db,job,state);db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
        String browser="/admin/migrations/"+job+"/conflicts/incident/"+MigrationSource.key(1);var fresh=result(h.get(path,auth("admin")));var form=decision(fresh,"keep_destination");assertEquals(403,h.form(browser,form,auth("admin")).statusCode());form.put("confirm","false");assertEquals(400,h.protectedForm(browser,form,auth("admin")).statusCode());form.put("confirm","true");assertEquals(302,h.protectedForm(browser,form,auth("admin")).statusCode());
        assertEquals(404,h.get(detail(job,id()),auth("admin")).statusCode());assertEquals(404,h.get(path.replace("/incident/","/unknown/"),auth("admin")).statusCode());
        try(var db=h.store.open()){db.update("DELETE FROM os_record WHERE sys_id=?",MigrationSource.key(1));db.connection.commit();}assertEquals(409,h.get(path,auth("admin")).statusCode());
    }
    static void restoreLink(WorkflowSupport h,Map<String,Object> link)throws Exception{try(var db=h.store.open()){db.update("INSERT INTO os_transfer_link(source_url,source_table,source_id,target_id,detail) VALUES(?,?,?,?,?) ON CONFLICT(source_url,source_table,source_id) DO UPDATE SET target_id=excluded.target_id,detail=excluded.detail",link.get("source_url"),link.get("source_table"),link.get("source_id"),link.get("target_id"),JSON.writeValueAsString(link.get("detail")));db.connection.commit();}}
    static void boundaries(WorkflowSupport h)throws Exception{
        h.account("ConflictApprover","admin");String job=prepare(h,1),sourceId=MigrationSource.key(1),path=detail(job,sourceId);Map<String,Object> link,current;try(var db=h.store.open()){link=db.one("SELECT * FROM os_transfer_link WHERE source_table='incident' AND source_id=?",sourceId);current=TransferApply.snapshot(db,"record",sourceId);}
        try(var db=h.store.open()){db.update("DELETE FROM os_transfer_link WHERE source_table='incident' AND source_id=?",sourceId);db.connection.commit();}assertEquals(404,h.get(path,auth("admin")).statusCode());restoreLink(h,link);
        for(var change:List.of(Map.entry("kind","account"),Map.entry("target",id()))){var altered=object(JSON.readValue(JSON.writeValueAsString(link),Object.class));object(altered.get("detail")).put(change.getKey(),change.getValue());restoreLink(h,altered);assertEquals(400,h.get(path,auth("admin")).statusCode());assertEquals(200,h.get(api(job),auth("admin")).statusCode());restoreLink(h,link);}
        result(h.json("POST",path,decision(result(h.get(path,auth("admin"))),"keep_destination"),auth("admin")));var baseline=object(object(link.get("detail")).get("destination"));try(var db=h.store.open()){db.update("UPDATE os_record SET data="+db.jsonParameter()+",revision=? WHERE sys_id=?",JSON.writeValueAsString(baseline.get("data")),baseline.get("revision"),sourceId);db.connection.commit();}assertEquals(200,h.get(api(job),auth("admin")).statusCode());assertEquals(409,h.get(path,auth("admin")).statusCode());assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_record SET data="+db.jsonParameter()+",revision=? WHERE sys_id=?",JSON.writeValueAsString(current.get("data")),current.get("revision"),sourceId);db.connection.commit();}
        result(h.json("POST",path,decision(result(h.get(path,auth("ConflictApprover"))),"use_source"),auth("ConflictApprover")));
        for(String change:List.of("active=0","active=1,role='agent'","active=1,role='admin',auth_revision=auth_revision+1")){try(var db=h.store.open()){db.update("UPDATE os_user SET "+change+" WHERE name='ConflictApprover'");db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());}
        try(var db=h.store.open()){db.update("DELETE FROM os_user WHERE name='ConflictApprover'");db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
        String fresh=MigrationStopsAcceptance.create(h);TransferAcceptance.fetch(h,fresh);var initialPage=h.get("/admin/migrations/"+fresh+"/reconciliation",auth("admin"));assertEquals(200,initialPage.statusCode());assertFalse(html(initialPage).contains("Review record conflict decisions"));assertEquals(false,result(h.get(api(fresh),auth("admin"))).get("editable"));assertEquals(400,h.get(detail(fresh,sourceId),auth("admin")).statusCode());
        String previous=object(result(h.get(TransferAcceptance.API+"/"+job,auth("admin"))).get("detail")).get("previous_job").toString();String sibling=result(h.json("POST",TransferAcceptance.API+"/"+previous+"/sync",map(),auth("admin"))).get("job_id").toString();TransferAcceptance.fetch(h,sibling);String siblingPath=detail(sibling,sourceId);result(h.json("POST",siblingPath,decision(result(h.get(siblingPath,auth("admin"))),"use_source"),auth("admin")));result(h.json("POST",TransferAcceptance.API+"/"+sibling+"/apply",map(),auth("admin")));assertEquals(409,h.get(path,auth("admin")).statusCode());assertEquals(409,h.get(api(job),auth("admin")).statusCode());
    }

    static void contexts(WorkflowSupport h)throws Exception{
        String job=prepare(h,1),sid=MigrationSource.key(1),path=detail(job,sid);Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");}
        try{
            var view=result(h.get(path,auth("admin")));var input=decision(view,"use_source");result(h.json("POST",path,input,auth("admin")));
            try(var db=h.store.open()){var source=object(db.one("SELECT data FROM os_transfer_item WHERE job_id=? AND source_id=?",job,sid).get("data"));source.put("short_description","Changed staged version");db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_id=?",JSON.writeValueAsString(source),job,sid);db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
            result(h.json("POST",path,decision(result(h.get(path,auth("admin"))),"use_source"),auth("admin")));
            try(var db=h.store.open()){var changed=new LinkedHashMap<>(schema);changed.put("label","Changed incident label");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(changed));db.connection.commit();}assertEquals(409,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
            var current=result(h.get(path,auth("admin")));try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"incident",sid),actor,map("visibility","workspace","owner_id",""));db.connection.commit();}assertEquals(409,h.json("POST",path,decision(current,"keep_destination"),auth("admin")).statusCode());
            try(var db=h.store.open()){var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(denied));db.connection.commit();}assertEquals(403,h.get(path,auth("admin")).statusCode());assertEquals(403,h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")).statusCode());
            try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));var source=object(db.one("SELECT data FROM os_transfer_item WHERE job_id=? AND source_id=?",job,sid).get("data"));source.put("priority","invalid");db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_id=?",JSON.writeValueAsString(source),job,sid);db.connection.commit();}assertEquals(400,h.get(path,auth("admin")).statusCode());
            try(var db=h.store.open()){var prior=object(db.one("SELECT detail FROM os_transfer_link WHERE source_table='incident' AND source_id=?",sid).get("detail"));var source=object(object(prior.get("source")).get("source"));db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_id=?",JSON.writeValueAsString(source),job,sid);db.connection.commit();}
            result(h.json("POST",path,decision(result(h.get(path,auth("admin"))),"use_source"),auth("admin")));result(h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")));assertEquals("Imported 1",object(record(h,1).get("data")).get("short_description"));
            String next=result(h.json("POST",TransferAcceptance.API+"/"+job+"/sync",map(),auth("admin"))).get("job_id").toString();TransferAcceptance.fetch(h,next);result(h.json("POST",TransferAcceptance.API+"/"+next+"/cancel",map("reason","Stop review"),auth("admin")));assertEquals(false,result(h.get(api(next),auth("admin"))).get("editable"));assertEquals(409,h.get(detail(next,sid),auth("admin")).statusCode());
        }finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(schema));db.connection.commit();}}
    }

}
